-- Generated by `engine types sync` from types/*.toml.
-- create type `article`; create type `author`; create type `settings`

CREATE TABLE content_article (
    id bigserial PRIMARY KEY,
    slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 80),
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    "title" text,
    "summary" text,
    "body" text,
    "author" bigint,
    "sections" jsonb
);
CREATE TRIGGER content_article_changes
    AFTER INSERT OR UPDATE OR DELETE ON content_article
    FOR EACH ROW EXECUTE FUNCTION engine_record_change('article');

CREATE TABLE content_author (
    id bigserial PRIMARY KEY,
    slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 80),
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    "name" text,
    "bio" text,
    "website" text
);
CREATE TRIGGER content_author_changes
    AFTER INSERT OR UPDATE OR DELETE ON content_author
    FOR EACH ROW EXECUTE FUNCTION engine_record_change('author');

CREATE TABLE content_settings (
    id bigserial PRIMARY KEY,
    slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 80),
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    "tagline" text,
    "footer_note" text
);
-- Singleton: at most one row.
CREATE UNIQUE INDEX content_settings_one ON content_settings ((true));
CREATE TRIGGER content_settings_changes
    AFTER INSERT OR UPDATE OR DELETE ON content_settings
    FOR EACH ROW EXECUTE FUNCTION engine_record_change('settings');

ALTER TABLE content_article ADD CONSTRAINT content_article_author_fk FOREIGN KEY ("author")
    REFERENCES content_author (id) ON DELETE SET NULL;
